To generate all possible unique combinations of a given set of integers in Go, you can use a recursive approach. Below is a Go function that accomplishes this task. The function takes a slice of integers as input, generates all possible combinations, and returns them as a slice of slices.

Here's the implementation:

```go
package main

import (
	"fmt"
	"sort"
)

// generateCombinations generates all unique combinations of the input set.
func generateCombinations(nums []int) [][]int {
	var results [][]int
	var current []int
	sort.Ints(nums) // Ensure the input is sorted to handle duplicates and maintain order
	backtrack(nums, 0, current, &results)
	return results
}

// backtrack is a helper function that generates combinations using recursion.
func backtrack(nums []int, start int, current []int, results *[][]int) {
	// Append a copy of current combination to results
	combination := make([]int, len(current))
	copy(combination, current)
	*results = append(*results, combination)

	for i := start; i < len(nums); i++ {
		// Skip duplicates
		if i > start && nums[i] == nums[i-1] {
			continue
		}
		// Include nums[i] in the combination
		current = append(current, nums[i])
		// Move on to the next element
		backtrack(nums, i+1, current, results)
		// Exclude nums[i] from the combination
		current = current[:len(current)-1]
	}
}

func main() {
	// Example input
	nums := []int{1, 2, 2}
	combinations := generateCombinations(nums)
	fmt.Println("Unique combinations:")
	for _, combo := range combinations {
		fmt.Println(combo)
	}
}
```

