import Foundation

func isPalindrome(_ string: String) -> Bool {
    // Create a character set that includes all letters and digits
    let allowedCharacters = CharacterSet.alphanumerics

    // Filter the input string to include only allowed characters and convert to lowercase
    let filteredString = string.unicodeScalars
        .filter { allowedCharacters.contains($0) }
        .map { Character($0).lowercased() }
        .joined()

    // Check if the filtered string is equal to its reversed version
    return filteredString == String(filteredString.reversed())
}

// Example usage:
let testString = "A man, a plan, a canal: Panama"
print(isPalindrome(testString))  // Output: true
```

### Explanation:
