  val DEBUG, INFO, WARN, ERROR = Value
}

// Trait for logging
trait Logger {
  val logFilePath: String

  // Method to log messages
  def log(level: LogLevel.Value, message: String): Unit = {
    val timestamp = LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME)
    val logMessage = s"$timestamp [${level.toString}] - $message"
    writeToFile(logMessage)
  }

  // Method to write logs to a file
  private def writeToFile(message: String): Unit = {
    try {
      val writer = new BufferedWriter(new FileWriter(logFilePath, true))
      writer.append(message).append("\n")
      writer.close()
    } catch {
      case e: IOException =>
        println(s"Failed to write log: ${e.getMessage}")
    }
  }
}

