    manageLogRotation()
  }

  // Manage log rotation
  private def manageLogRotation(): Unit = {
    val maxSize = 10 * 1024 * 1024 // 10 MB
    val path = Paths.get(logFilePath)
    val fileSize = Files.size(path)

    if (fileSize > maxSize) {
      val rotatedFilePath = logFilePath + "." + System.currentTimeMillis()
      Files.move(path, Paths.get(rotatedFilePath))
      initializeLogFile() // Create a new log file
    }
  }
}

